var context by remember {
    mutableStateOf(
        listOf(
            MonarchAiContextItem({{context.id}}, MonarchAiContextKind.{{context.kind|pascal}}, {{context.label}}, tokens = {{context.tokens}}, removable = {{context.removable}}),
        ),
    )
}

